"""Fixture generated by executing actual LibreChat e8f3be08 TS, not inferred JSON.

Reproduce via scripts/generate-actions-oracle.cjs with ts-node dev dependencies.
No Node dependency in the Python controller or CI test runtime.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

import pytest

from local_shell_mcp.webui.action_spec import (
    is_action_tool,
    normalize_action_tool_name,
    operations,
    parse_spec,
    validate_domain,
)

REPO = Path(__file__).resolve().parents[1]
ORACLE = json.loads((REPO / "tests/fixtures/librechat/actions_source_oracle.json").read_text())


def test_exact_upstream_source_hashes():
    for path, expected in ORACLE["hashes"].items():
        assert hashlib.sha256((REPO / path).read_bytes()).hexdigest() == expected, path
    assert "e8f3be08623663d4ad7f7241e693c94469b63bb0" in ORACLE["source"]


@pytest.mark.parametrize("entry", ORACLE["outputs"], ids=[
    f"spec-{n}" for n in range(len(ORACLE["outputs"]))
])
def test_openapi_parser_schema_and_tool_builder_exact_oracle(entry):
    spec = parse_spec(json.dumps(entry["spec"]))
    ours = operations(spec)
    expected = entry["functions"]
    tools = []
    for operation in ours.values():
        func = {"name": operation["name"], "description": operation["description"],
                "parameters": operation["parameters"]}
        if operation["strict"]:
            func["strict"] = True
        tools.append({"type": "function", "function": func})
    assert tools == expected
    assert len(ours) == len(entry["builders"])
    for name, result in ours.items():
        expected = entry["builders"][name]
        assert result["method"] == expected["method"]
        assert result["path"] == expected["basePath"]
        assert result["description"] == next(
            tool["function"]["description"] for tool in tools if tool["function"]["name"] == name
        )
        assert result["content_type"] == expected["contentType"]
        assert result["consequential"] == expected["isConsequential"]
        assert result["locations"] == expected["parameterLocations"]
        assert spec["servers"][0]["url"] == expected["domain"]


@pytest.mark.parametrize("entry", ORACLE["tool_vectors"], ids=[
    str(n) for n in range(len(ORACLE["tool_vectors"]))
])
def test_action_tool_detection_normalization_exact_oracle(entry):
    assert is_action_tool(entry["name"]) == entry["isAction"]
    assert normalize_action_tool_name(entry["name"]) == entry["normalized"]


@pytest.mark.parametrize("entry", ORACLE["domains"], ids=[
    str(n) for n in range(len(ORACLE["domains"]))
])
def test_action_domain_validator_source_oracle(entry):
    try:
        validate_domain(entry["domain"], entry["server"])
        valid = True
    except ValueError:
        valid = False
    assert valid == entry["isValid"], entry
